// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "PUT", "template": "/v1/profiles/me", "require_user": true, "idempotent": true, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.profiles_me > "Validate body"
// PUT /v1/profiles/me: save or correct the caller's search profile. The whole profile is
// sent (fields left out become empty). Money in minor units of currency (spec 4.2).
// Small JSON Schema validator for LLM outputs and request bodies (spec 9.2: validate every
// output against its schema). n8n Code nodes cannot load packages (no require), so this
// covers the subset the schemas in prompts/schemas/ use: type (one or a list, including
// "null" and "integer"), enum, const, required, properties, additionalProperties (boolean
// or schema), items, minItems, maxItems, minimum, maximum, minLength, maxLength, pattern.
// Anything else in a schema is ignored. Cross-checked against the Python jsonschema package
// in tests/unit/test_prompts.py.
// Returns a list of errors [{path, issue, ...}]; empty when the value is valid.

function typeOf(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (typeof v === 'number') return Number.isInteger(v) ? 'integer' : 'number';
  return typeof v;            // string, boolean, object
}

function typeMatches(t, v) {
  const actual = typeOf(v);
  if (t === actual) return true;
  if (t === 'number' && actual === 'integer') return true;
  return false;
}

function validate(schema, value, path = '$', errors = []) {
  if (!schema || typeof schema !== 'object') return errors;
  if (schema.type !== undefined) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    if (!types.some((t) => typeMatches(t, value))) {
      errors.push({ path, issue: 'type', expected: types.join('|'), got: typeOf(value) });
      return errors;
    }
  }
  if (schema.enum !== undefined && !schema.enum.some((e) => e === value)) {
    errors.push({ path, issue: 'enum', allowed: schema.enum });
  }
  if (schema.const !== undefined && schema.const !== value) errors.push({ path, issue: 'const' });
  const t = typeOf(value);
  if (t === 'string') {
    // length in code points, as JSON Schema counts it
    const len = Array.from(value).length;
    if (schema.minLength !== undefined && len < schema.minLength) errors.push({ path, issue: 'minLength', min: schema.minLength });
    if (schema.maxLength !== undefined && len > schema.maxLength) errors.push({ path, issue: 'maxLength', max: schema.maxLength });
    if (schema.pattern !== undefined && !new RegExp(schema.pattern, 'u').test(value)) errors.push({ path, issue: 'pattern' });
  }
  if (t === 'integer' || t === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push({ path, issue: 'minimum', min: schema.minimum });
    if (schema.maximum !== undefined && value > schema.maximum) errors.push({ path, issue: 'maximum', max: schema.maximum });
  }
  if (t === 'array') {
    if (schema.minItems !== undefined && value.length < schema.minItems) errors.push({ path, issue: 'minItems', min: schema.minItems });
    if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push({ path, issue: 'maxItems', max: schema.maxItems });
    if (schema.items) value.forEach((v, i) => validate(schema.items, v, `${path}[${i}]`, errors));
  }
  if (t === 'object') {
    for (const k of schema.required || []) {
      if (!Object.prototype.hasOwnProperty.call(value, k)) errors.push({ path: `${path}.${k}`, issue: 'required' });
    }
    const props = schema.properties || {};
    for (const [k, v] of Object.entries(value)) {
      if (Object.prototype.hasOwnProperty.call(props, k)) validate(props[k], v, `${path}.${k}`, errors);
      else if (schema.additionalProperties === false) errors.push({ path: `${path}.${k}`, issue: 'additional_property' });
      else if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
        validate(schema.additionalProperties, v, `${path}.${k}`, errors);
      }
    }
  }
  return errors;
}

// One line per error, for retry prompts and logs.
function describe(errors, max = 8) {
  return errors.slice(0, max).map((e) => {
    switch (e.issue) {
      case 'type': return `${e.path}: expected ${e.expected}, got ${e.got}`;
      case 'enum': return `${e.path}: must be one of ${JSON.stringify(e.allowed)}`;
      case 'required': return `${e.path}: missing`;
      case 'additional_property': return `${e.path}: not allowed`;
      default: return `${e.path}: ${e.issue}`;
    }
  }).join('; ');
}

if (typeof module !== 'undefined') module.exports = { validate, describe, typeOf };

const gw = $input.first().json;
const b = gw.ctx.body || {};
const nint = (max) => ({ type: ['integer', 'null'], minimum: 0, maximum: max });
const PREF = { type: 'string' };
const schema = {
  type: 'object', additionalProperties: false, required: ['jurisdiction_code'],
  properties: {
    jurisdiction_code: { type: 'string', pattern: '^[A-Z]{2}(-[A-Z0-9]{1,3})?$' },
    budget_min_minor: nint(1e12), budget_max_minor: nint(1e12),
    currency: { type: ['string', 'null'], pattern: '^[A-Z]{3}$' },
    budget_period: { type: ['string', 'null'], enum: ['month', 'week', null] },
    anchor_label: { type: ['string', 'null'], maxLength: 120 },
    anchor_lat: { type: ['number', 'null'], minimum: -90, maximum: 90 },
    anchor_lng: { type: ['number', 'null'], minimum: -180, maximum: 180 },
    max_commute_min: nint(300), search_radius_m: { type: ['integer', 'null'], minimum: 100, maximum: 100000 },
    move_in_from: { type: ['string', 'null'], pattern: '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' },
    min_stay_months: nint(120),
    declared_preferences: { type: 'object', additionalProperties: false, properties: {
      smoking: { ...PREF, enum: ['yes', 'no'] }, pets: { ...PREF, enum: ['yes', 'no'] }, quiet_hours: { ...PREF, enum: ['yes', 'no'] },
      guests: { ...PREF, enum: ['yes', 'no'] }, schedule: { ...PREF, enum: ['early', 'late', 'irregular'] },
      cleanliness: { ...PREF, enum: ['high', 'medium', 'relaxed'] } } },
    languages: { type: 'array', maxItems: 6, items: { type: 'string', enum: ['ar', 'aeb', 'fr', 'en', 'de', 'es', 'it'] } },
    unparsed: { type: 'array', maxItems: 10, items: { type: 'string', maxLength: 200 } },
  },
};
const errors = validate(schema, b);
const details = errors.map((e) => ({ field: e.path.replace(/^\$\.?/, '') || 'body', issue: e.issue }));
if (!errors.length) {
  if ((b.budget_min_minor != null || b.budget_max_minor != null) && !b.currency) details.push({ field: 'currency', issue: 'required_with_budget' });
  if (b.budget_min_minor != null && b.budget_max_minor != null && b.budget_min_minor > b.budget_max_minor) details.push({ field: 'budget_min_minor', issue: 'greater_than_max' });
  if ((b.anchor_lat == null) !== (b.anchor_lng == null)) details.push({ field: 'anchor_lat', issue: 'lat_and_lng_go_together' });
  if (b.move_in_from && Number.isNaN(Date.parse(b.move_in_from + 'T00:00:00Z'))) details.push({ field: 'move_in_from', issue: 'invalid_date' });
  else if (b.move_in_from && new Date(b.move_in_from + 'T00:00:00Z').toISOString().slice(0, 10) !== b.move_in_from) details.push({ field: 'move_in_from', issue: 'invalid_date' });
}
if (details.length) {
  return [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
}
const body = { ...b, budget_period: b.budget_period || ((b.budget_min_minor != null || b.budget_max_minor != null) ? 'month' : null) };
return [{ json: { ok: true, gw, params: [gw.ctx.user_id, JSON.stringify(body)] } }];

// wf.api.profiles_me > "Build result" / "Save failed"
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const v = $('Validate body').first().json;
const r = $input.first().json;
if (r.saved) return [{ json: { ok: true, gw: v.gw, status: 200, data: r.saved } }];
// unknown jurisdiction or currency (foreign key), or a check constraint
const msg = errorText(r);
const field = /currency/.test(msg) ? 'currency' : /jurisdiction/.test(msg) ? 'jurisdiction_code' : 'body';
return [{ json: { ok: false, gw: v.gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid',
  details: [{ field, issue: 'rejected_by_database' }] }, log: { reason: 'save_profile', detail: redactPg(msg).slice(0, 200) } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
